678			Data:   base64.StdEncoding.EncodeToString([]byte("payload")),
679		}
680		goodSnap := Snapshot{Name: "s", Entries: map[string]Entry{
681			"a.txt": {Name: "a.txt", Digest: d, Size: int64(len("payload")), CreatedAt: stamp},
682		}}
683		encode := func(pkg Package) []byte {
684			data, err := json.Marshal(&pkg)
685			if err != nil {
686				t.Fatal(err)
687			}
688			return data
689		}
690		base := func() Package {
691			return Package{
692				Format:   packageFormat,
693				Version:  packageVersion,
694				Snapshot: goodSnap,
695				Objects:  []PackageObject{goodObj},
696			}
697		}
698	
699		cases := map[string]func() Package{
700			"unknown version": func() Package {
701				p := base()
702				p.Version = 99
703				return p
704			},
705			"unknown format": func() Package {
706				p := base()
707				p.Format = "something-else"
708				return p
709			},
710			"bad snapshot name": func() Package {
711				p := base()
712				p.Snapshot = Snapshot{Name: "../escape", Entries: map[string]Entry{
713					"../escape": {Name: "../escape", Digest: d, Size: 7, CreatedAt: stamp},
714				}}
715				return p
716			},
717			"bad entry name": func() Package {
718				p := base()
719				p.Snapshot.Entries["a.txt"] = Entry{Name: "b.txt", Digest: d, Size: 7, CreatedAt: stamp}
720				return p
721			},
722			"bad digest": func() Package {
723				p := base()
724				p.Objects[0].Digest = strings.Repeat("z", 64)
725				return p
726			},
727			"negative size": func() Package {
728				p := base()
729				p.Objects[0].Size = -1
730				return p
731			},
732			"checksum mismatch": func() Package {
733				p := base()
734				p.Objects[0].Digest = digestOf("other")
735				return p
736			},
737			"declared size mismatch": func() Package {
738				p := base()
739				p.Objects[0].Size = 999
740				return p
741			},
742			"bad base64": func() Package {
743				p := base()
744				p.Objects[0].Data = "!!!not base64!!!"
745				return p
746			},
747			"missing content": func() Package {
748				p := base()
749				p.Objects = []PackageObject{}
750				return p
751			},
752			"extra object": func() Package {
753				p := base()
754				p.Objects = append(p.Objects, PackageObject{
755					Digest: digestOf("extra"), Size: 5,
756					Data: base64.StdEncoding.EncodeToString([]byte("extra")),
757				})
758				return p
759			},
760			"duplicate object": func() Package {
761				p := base()
762				p.Objects = append(p.Objects, goodObj)
763				return p
764			},
765		}
766		for label, build := range cases {
767			t.Run(label, func(t *testing.T) {
768				if _, err := decodePackage(encode(build())); err == nil {
769					t.Fatalf("decode accepted %s", label)
770				}
771			})
772		}
773	
774		t.Run("duplicate json key", func(t *testing.T) {
775			bad := strings.Replace(string(encode(base())), `"version":1`, `"version":1,"version":1`, 1)
776			if _, err := decodePackage([]byte(bad)); err == nil {
