	// top-level value.
	if err := json.Unmarshal(data, &idx); err != nil {
		return index{}, fmt.Errorf("current index is corrupt: %w", err)
	}
	if idx.Entries == nil {
		return index{}, errors.New("current index is corrupt: missing entries mapping")
	}
