		Version:  packageVersion,
		Snapshot: Snapshot{Name: "s", Entries: map[string]Entry{"empty.txt": entryRec("empty.txt", d0, 0)}},
		Objects:  []PackageObject{{Digest: d0, Size: 0, Data: ""}},
